def ohlc_bars(trades, bar_ms):
    out = []; cur = None
    for t, px, q in trades:
        start = t - t % bar_ms
        if cur is None or cur[0] != start:
            if cur: out.append(cur[:6] + [cur[6] / cur[5]])
            cur = [start, px, px, px, px, 0, 0.0]
        cur[2] = max(cur[2], px); cur[3] = min(cur[3], px); cur[4] = px; cur[5] += q; cur[6] += px * q
    if cur: out.append(cur[:6] + [cur[6] / cur[5]])
    return out

