vector<vector<double>> ohlcBars(vector<vector<double>>& tr, long long bar) {
    vector<vector<double>> out; bool open = false; double s = 0, o = 0, h = 0, l = 0, c = 0, vol = 0, pv = 0;
    for (auto& x : tr) { long long t = (long long)x[0]; double start = (double)(t - t % bar), px = x[1], q = x[2];
        if (!open || start != s) { if (open) out.push_back({s, o, h, l, c, vol, pv / vol}); open = true; s = start; o = h = l = c = px; vol = 0; pv = 0; }
        h = max(h, px); l = min(l, px); c = px; vol += q; pv += px * q; }
    if (open) out.push_back({s, o, h, l, c, vol, pv / vol});
    return out;
}
